## 问题1 [implementation]
你在实现 `sys_trace` 的 `trace_request=2` 功能（查询系统调用次数）时，需要维护每个任务的系统调用统计信息。请看这段可能的实现代码：

<code>
// os/src/syscall/proc.c
int sys_trace(int trace_request, unsigned long id, uint8_t data) {
    struct TaskControlBlock *current = get_current_task();
    switch (trace_request) {
    case 0:
        // 读取内存...
        return *(uint8_t*)id;
    case 1:
        // 写入内存...
        *(uint8_t*)id = data;
        return 0;
    case 2:
        // 查询系统调用次数
        if (id >= MAX_SYSCALL_NUM) return -1;
        return current->syscall_count[id];  // 返回计数
    default:
        return -1;
    }
}
</code>

<code>
// os/src/trap/trap.c
void trap_handler(struct trapframe *tf) {
    uint64_t scause = csr_read(scause);
    if (scause == CAUSE_USER_ECALL) {
        uint64_t syscall_id = tf->a7;
        struct TaskControlBlock *current = get_current_task();

        // 在系统调用入口处增加计数
        if (syscall_id < MAX_SYSCALL_NUM) {
            current->syscall_count[syscall_id]++;
        }

        syscall(tf);
    }
